 private readonly PacketPanel signalingPanel=new(),weakPanel=new(),meshPanel=new();private readonly TextBlock signalingStatus=new(){Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap},weakStatus=new(){Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap},meshStatus=new(){Foreground=Brushes.Aquamarine,TextWrapping=TextWrapping.Wrap};
 private readonly CheckBox sameDecode=new(){Content="SAME / EAS headers",Foreground=Brushes.Gainsboro},dtmfDecode=new(){Content="DTMF",Foreground=Brushes.Gainsboro},mdcDecode=new(){Content="MDC1200",Foreground=Brushes.Gainsboro},fleetDecode=new(){Content="FleetSync",Foreground=Brushes.Gainsboro};
 private readonly ComboBox weakMode=new(){ItemsSource=new[]{"FT8","FT4","WSPR"},SelectedIndex=0,Width=100};private readonly TextBox weakOffset=new(){Text="0",Width=65};private readonly ComboBox meshMode=new(){ItemsSource=new[]{"Meshtastic","MeshCore","Generic LoRa"},SelectedIndex=0,Width=135},meshSf=new(){ItemsSource=Enumerable.Range(7,6).ToArray(),SelectedItem=11,Width=65},meshBw=new(){ItemsSource=new[]{62500,125000,250000,500000},SelectedItem=250000,Width=105},meshCr=new(){ItemsSource=new[]{1,2,3,4},SelectedItem=1,Width=55};private readonly TextBox meshFrequency=new(){Text="906.875000",Width=120},meshSync=new(){Text="43",Width=50};private readonly CheckBox meshPublic=new(){Content="Decode known Public channel",IsChecked=true,Foreground=Brushes.Gainsboro};private TabItem? signalingTab,weakTab,meshTab;
 private PacketContext RadioContext(string kind,long? hz,double? pos=null)=>new($"{workspaceSlot}:{kind}:{Interlocked.Read(ref session)}:{hz}",$"Receiver {workspaceSlot} · "+(rfMode?(receiver.IsReplay?"I/Q replay":receiver.ReceiverName):packetAudioSource),rfMode?receiver.IsReplay:packetAudioReplay,hz,pos);
 private void InitializeRadioData()
 {
  TabItem Page(TabControl tabs,string name,PacketPanel panel,TextBlock status,Action<WrapPanel> build,string help){panel.ConfigureWorkspace("RadioData");panel.ShowUnverified(true);var root=new DockPanel{Margin=new(6)};var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);var bar=new WrapPanel();top.Children.Add(bar);build(bar);top.Children.Add(status);if(help.Length>0)top.Children.Add(new TextBlock{Text=help,Foreground=Brushes.LightSteelBlue,TextWrapping=TextWrapping.Wrap,Margin=new(0,5,0,5)});root.Children.Add(panel);var tab=new TabItem{Header=name,Content=root};tabs.Items.Add(tab);return tab;}
  void Button(Panel row,string title,Action action){var b=new Button{Content=title,Padding=new(8,5,8,5),Margin=new(4,0,0,4)};row.Children.Add(b);b.Click+=(_,_)=>{try{action();}catch(Exception ex){Log(title+": "+ex.Message);MessageBox.Show(this,ex.Message,title);}};}
  signalingTab=Page((TabControl)ProfessionalTab.Content,"Signaling / alerts",signalingPanel,signalingStatus,row=>{foreach(var c in new[]{sameDecode,dtmfDecode,mdcDecode,fleetDecode}){c.Margin=new(4,3,10,3);row.Children.Add(c);c.Checked+=(_,_)=>ConfigureSignaling();c.Unchecked+=(_,_)=>ConfigureSignaling();}Button(row,"Stop all",()=>{sameDecode.IsChecked=dtmfDecode.IsChecked=mdcDecode.IsChecked=fleetDecode.IsChecked=false;});Button(row,"Help",()=>new HelpWindow(Path.Combine(AppContext.BaseDirectory,"Help"),"Signaling"){Owner=this}.Show());},"Receive only · NFM discriminator or flat radio/WAV audio. SAME/EAS and DTMF are candidates, not authenticated alerts; repeated header evidence is retained. MDC/FleetSync IDs do not identify an organization without your labels. No alert relaying or radio commands.");
  weakTab=Page((TabControl)AmateurTab.Content,"FT8 / FT4 / WSPR",weakPanel,weakStatus,row=>{row.Children.Add(weakMode);Button(row,"Start decoding",()=>{if(rfMode&&receiver.AppliedChannel?.Mode!="USB")throw new IOException("Select USB and a receive filter covering the intended audio passband (typically 3–4 kHz). Start SDR or I/Q replay first.");if(!double.TryParse(weakOffset.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out double offset)||!double.IsFinite(offset)||Math.Abs(offset)>10)throw new IOException("Enter a time offset from -10 to +10 seconds.");manualWeakOffset=offset;rxWeakOffset=0;rxTiming.Reset();weakData.Configure(weakMode.SelectedItem?.ToString()??"FT8",EffectiveWeakOffset);});Button(row,"Stop",()=>weakData.Configure(""));InitializeWeakTiming(row);Button(row,"Transmit…",OpenWeakTransmit);Button(row,"Help",()=>new HelpWindow(Path.Combine(AppContext.BaseDirectory,"Help"),"Weak signal"){Owner=this}.Show());},"");weakPanel.InitializeWeakView(Path.Combine(dataFolder,"weak-view.json"));InitializePskReporting((Panel)weakTimingExpander.Parent);
  meshTab=Page(AnalysisTabs,"Meshtastic / MeshCore",meshPanel,meshStatus,row=>{foreach(var c in new FrameworkElement[]{meshMode,new TextBlock{Text="MHz",Foreground=Brushes.Gainsboro},meshFrequency,new TextBlock{Text="SF",Foreground=Brushes.Gainsboro},meshSf,new TextBlock{Text="BW Hz",Foreground=Brushes.Gainsboro},meshBw,new TextBlock{Text="CR +4",Foreground=Brushes.Gainsboro},meshCr,new TextBlock{Text="Sync decimal",Foreground=Brushes.Gainsboro},meshSync,meshPublic}){c.Margin=new(3,2,3,2);row.Children.Add(c);}Button(row,"Start mesh reception",()=>{if(!rfMode)throw new IOException("Start an SDR or I/Q replay first. Mesh reception uses raw I/Q, not speaker audio.");meshData.Start(new(meshMode.SelectedItem?.ToString()??"Meshtastic",ParseMHz(meshFrequency.Text),(int)meshSf.SelectedItem,(int)meshBw.SelectedItem,(int)meshCr.SelectedItem,int.Parse(meshSync.Text,CultureInfo.InvariantCulture),meshPublic.IsChecked==true));});Button(row,"Stop mesh",meshData.Stop);Button(row,"Help",()=>new HelpWindow(Path.Combine(AppContext.BaseDirectory,"Help"),"Mesh"){Owner=this}.Show());},"Direct SDR/IQ reception · match the actual frequency, SF, bandwidth, coding rate and sync. Meshtastic US LongFast starting profile: 906.875 MHz / SF11 / 250 kHz / CR4/5 / sync43. MeshCore uses separate network-specific settings (sync18); it is not interoperable with Meshtastic. Unknown/private payloads stay encrypted; advertisements are not signature-verified.");
  meshMode.SelectionChanged+=(_,_)=>{if(meshMode.SelectedIndex==0){meshSf.SelectedItem=11;meshBw.SelectedItem=250000;meshCr.SelectedItem=1;meshSync.Text="43";meshFrequency.Text="906.875000";}else if(meshMode.SelectedIndex==1){meshSf.SelectedItem=8;meshBw.SelectedItem=62500;meshCr.SelectedItem=4;meshSync.Text="18";meshFrequency.Text="";meshStatus.Text="MeshCore: enter your actual local network frequency and parameters before starting.";}else meshSync.Text="0";meshData.Stop();};weakMode.SelectionChanged+=(_,_)=>weakData.Configure("");
  foreach(var panel in new[]{signalingPanel,weakPanel,meshPanel})panel.ClearRequested+=()=>{};
  receiver.DataSamples+=samples=>{if(receiver.AppliedChannel is not {Mode:"NFM"} channel)return;var c=RadioContext("signaling",channel.Frequency,receiver.IsReplay?receiver.ReplayPosition.TotalSeconds:null);double[] pcm=samples.Select(v=>v*2.5).ToArray();signalingData.Feed(pcm,c,0);aniData.Feed(pcm,c,0);};
  receiver.Audio+=pcm=>{if(receiver.AppliedChannel is not {} ch)return;if(ch.Mode is "AM" or "WFM"){var c=RadioContext("signaling-audio",ch.Frequency,receiver.IsReplay?receiver.ReplayPosition.TotalSeconds:null);signalingData.FeedPcm(pcm,1,c,0);aniData.FeedPcm(pcm,1,c,0);}if(ch.Mode!="USB"||!weakData.Enabled)return;double pos=receiver.IsReplay?receiver.ReplayPosition.TotalSeconds:0;double t=receiver.IsReplay?(receiver.ReplayStartedUtc.ToUnixTimeMilliseconds()/1000.0+pos):(DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000.0-pcm.Length/96000.0);weakData.FeedPcm(pcm,1,RadioContext("weak",ch.Frequency,receiver.IsReplay?pos:null),t,!receiver.IsReplay);};
  receiver.RawIq+=frame=>meshData.Feed(frame,RadioContext("mesh",frame.Channel?.Frequency??frame.Frequency,receiver.IsReplay?receiver.ReplayPosition.TotalSeconds:null));
  engine.PcmReady+=(bytes,count,channels,pos)=>{if(rfMode)return;var c=RadioContext("audio-data",null,pos);double time=packetAudioReplay?pos:DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()/1000.0-count/(96000.0*channels);signalingData.FeedPcm(bytes.AsSpan(0,count),channels,c,time);aniData.FeedPcm(bytes.AsSpan(0,count),channels,c,time);weakData.FeedPcm(bytes.AsSpan(0,count),channels,c,time,!packetAudioReplay);};
  void Reset(){Interlocked.Exchange(ref resetRxTiming,1);signalingData.Reset();aniData.Reset();weakData.Reset();meshData.Reset();}receiver.ChannelChanged+=Reset;receiver.ReplayGap+=Reset;engine.PcmBoundary+=()=>{if(Interlocked.Exchange(ref radioCompletedBoundary,0)==0)Reset();};receiver.Ended+=_=>{Interlocked.Exchange(ref radioCompletedBoundary,1);signalingData.Complete();aniData.Complete();weakData.Complete();meshData.Complete();};engine.Ended+=_=>{Interlocked.Exchange(ref radioCompletedBoundary,1);signalingData.Complete();aniData.Complete();weakData.Complete();};Closed+=(_,_)=>{signalingData.Dispose();aniData.Dispose();weakData.Dispose();meshData.Dispose();};
  int order=0;foreach(var panel in new[]{signalingPanel,weakPanel,meshPanel})monitorOrders.Add(new(panel.MonitorGrid,Path.Combine(dataFolder,"radio-data-order-"+(order++)+".json"),showClear:!ReferenceEquals(panel,weakPanel)));
