 private void ConfigureSignaling(){signalingData.Configure(sameDecode.IsChecked==true||dtmfDecode.IsChecked==true?"Signaling":"");aniData.Configure(mdcDecode.IsChecked==true||fleetDecode.IsChecked==true?"ANI":"");UpdateDataCapture();}
 private void TickRadioData(){signalingStatus.Text=signalingData.Status+" · ANI: "+aniData.Status;weakStatus.Text=weakData.Status;meshStatus.Text=meshData.Status;foreach(var p in signalingData.Drain())if(p.Protocol=="DTMF"?dtmfDecode.IsChecked==true:sameDecode.IsChecked==true)signalingPanel.Add(p);foreach(var p in aniData.Drain())if(p.Protocol=="MDC1200"?mdcDecode.IsChecked==true:fleetDecode.IsChecked==true)signalingPanel.Add(p);foreach(var p in weakData.Drain()){weakPanel.Add(p);QueuePskReport(p);if(rfMode&&!receiver.IsReplay&&p.SourceKey==RadioContext("weak",receiver.AppliedChannel?.Frequency).Key)weakTransmitWindow?.Observe(p);if(p.SourceKey==RadioContext(rfMode?"weak":"audio-data",rfMode?receiver.AppliedChannel?.Frequency:null).Key){using var timingJson=System.Text.Json.JsonDocument.Parse(p.DecoderJson??"{}");if(timingJson.RootElement.TryGetProperty("mrs_epoch",out var epoch)&&epoch.GetInt64()==weakData.TimingEpoch)rxTiming.Observe(p);}}foreach(var cycle in weakData.DrainCycles())weakPanel.BeginWeakCycle(cycle.Source,cycle.Slot,cycle.Mode,cycle.Epoch);TickWeakTiming();TickPskReporting();TickAprsInternet();foreach(var p in meshData.Drain())meshPanel.Add(p);}
